"""AgentRun CRD (generated by crossplane-runtime xcrd from xrds/agentrun.yaml) against a real kube-apiserver.
Usage: python3 test_xrd_cel.py <kubeconfig of a scratch apiserver with the CRD applied> (see README.md). Never a real cluster:
it creates and patches an AgentRun."""
import json, subprocess, sys, copy
K = ["kubectl", "--kubeconfig", sys.argv[1]]
DIG = "ghcr.io/x/agent@sha256:" + "0" * 64
def xr(name="r-1a2b3c", **spec):
    s = {"agent": "coding-agent", "image": DIG, "sandbox": "standard", "compute": "small", "network": {"mode": "clearance"},
         "expiresAt": "2099-01-01T00:30:00Z", "taskId": "t-1a2b3c", "sessionId": "s-1a2b3c",
         "limits": {"toolCalls": 1, "githubCalls": 1, "modelTokens": 1}}
    s.update(spec)
    return {"apiVersion": "catalog.hangar.io/v1alpha1", "kind": "AgentRun", "metadata": {"name": name, "namespace": "autopilot-runs"}, "spec": s}
def kc(args, doc=None):
    r = subprocess.run(K + args, input=json.dumps(doc) if doc else None, capture_output=True, text=True)
    return r.returncode == 0, (r.stdout + r.stderr).strip()
results = []
def expect(name, ok_wanted, ok, out, needle=None):
    passed = ok == ok_wanted and (needle is None or needle in out)
    results.append(passed)
    print(("PASS" if passed else "FAIL"), name, "" if passed else "\n     " + out[-300:])
def create(doc, dry=True):
    return kc(["create", "-f", "-"] + (["--dry-run=server"] if dry else []), doc)
expect("a valid run is accepted", True, *create(xr()))
expect("a name that is not r-<hex> is refused", False, *create(xr(name="my-run")), "r-<session hex>")
expect("an image tag instead of a digest is refused", False, *create(xr(image="ghcr.io/x/agent:latest")))
expect("allowlist without allowCidrs is refused", False, *create(xr(network={"mode": "allowlist"})), "allowCidrs is required")
expect("allowCidrs with mode clearance is refused", False, *create(xr(network={"mode": "clearance", "allowCidrs": ["10.0.0.0/8"]})), "allowCidrs is required")
expect("a /0 is refused by the pattern", False, *create(xr(network={"mode": "allowlist", "allowCidrs": ["0.0.0.0/0"]})))
expect("an allowlist with a /24 is accepted", True, *create(xr(network={"mode": "allowlist", "allowCidrs": ["203.0.113.0/24"]})))
expect("a sidecar named agent is refused", False, *create(xr(sidecars=[{"name": "agent", "image": DIG}])), "agent container")
expect("an unknown compute class is refused", False, *create(xr(compute="huge")))
ok, out = create(xr(), dry=False); expect("create the real run", True, ok, out)
def patch(p, sub=None):
    return kc(["patch", "agentrun", "r-1a2b3c", "-n", "autopilot-runs", "--type=merge", "-p", json.dumps(p)])
expect("extending expiresAt is refused", False, *patch({"spec": {"expiresAt": "2099-01-01T05:00:00Z"}}), "never extended")
expect("changing the image is refused", False, *patch({"spec": {"image": "ghcr.io/x/other@sha256:" + "1" * 64}}))
expect("widening the network is refused", False, *patch({"spec": {"network": {"mode": "clearance+model"}}}))
expect("raising limits is refused", False, *patch({"spec": {"limits": {"toolCalls": 999}}}))
expect("adding an input after creation is refused", False, *patch({"spec": {"input": {"a": 1}}}), "fixed at creation")
expect("Crossplane may still write spec.crossplane", True, *patch({"spec": {"crossplane": {"compositionRef": {"name": "agentruns-copy"}}}}))
expect("freezing is allowed (Clearance's patch)", True, *patch({"spec": {"frozen": True}}))
expect("unfreezing is refused", False, *patch({"spec": {"frozen": False}}), "can't be unfrozen")
print(f"\n{sum(results)}/{len(results)} CEL checks pass")
sys.exit(0 if all(results) else 1)
